[x, Fs] = audioread('FIRE.mp3');
x=mean(x,2); %convert x from stereo to mono to make it enable in conv fn
Ts = 1/Fs;
%sound(x,Fs);
% 1-Transmitter
%plotting audio in time domain 
t = (0:length(x)-1)*Ts; % we got Samples "n" from length(x) fn ,t=nTs
figure(1) %[output:23029d09]
subplot(2,1,1) %[output:23029d09]
plot(t,x); %[output:23029d09]
xlabel('Time (s)'); %[output:23029d09]
ylabel('Amplitude'); %[output:23029d09]
%xlim([0.2 0.21]);
title('Audio signal in time domain');  %[output:23029d09]
grid on; %[output:23029d09]
%plotting audio in freq domain
X = fft(x);
n = length(X);
f = (-n/2:n/2-1) * Fs/n; 
subplot(2,1,2) %[output:23029d09]
plot(f,fftshift(abs(X))); %[output:23029d09]
xlabel('Frequency (Hz)'); %[output:23029d09]
ylabel('Magnitude'); %[output:23029d09]
title('Audio signal in frequency domain'); %[output:23029d09]
grid on; %[output:23029d09]



% 2-Channel 

to=(0:Ts:0.01)'; %convert t to vector to make it enable in conv fn 
h1=[1];
h2=exp(-2*pi*5000*to);
h3=exp(-2*pi*1000*to);
h4= [2 0.5];




h=h1; %change value of h w.r.t the needed channel




y=conv(x,h);
ty=(0:length(y)-1)/Fs;
%plotting in time domain after passing through channel
figure(2) %[output:0a805023]
subplot(2,1,1) %[output:0a805023]
plot(ty,y,'m'); %[output:0a805023]
xlabel('Time (s)'); %[output:0a805023]
%xlim([0.2 0.21]);
ylabel('Amplitude'); %[output:0a805023]
title('Signal in time After passing through channel'); %[output:0a805023]
grid on; %[output:0a805023]
%plotting in frequency domain after passing through channel
Ny = length(y);
fy=(-Ny/2:Ny/2-1)*Fs/Ny;
subplot(2,1,2) %[output:0a805023]
Y=fft(y);
plot(fy,fftshift(abs(Y)),'m') %[output:0a805023]
xlabel('Frequency (Hz)'); %[output:0a805023]
ylabel('Magnitude'); %[output:0a805023]
title('Audio in frequency After passing through channel'); %[output:0a805023]
grid on; %[output:0a805023]
%sound(y,Fs);


% 3-Noise

sigma = input('Enter sigma value: ');
NOISE = sigma * randn(length(y),1); 
y_n=y+NOISE ;
t_n = (0:length(y_n)-1)/Fs;
%sound(y_n,Fs);

%plotting in time domain after adding noise
figure(3) %[output:945efd8d]
subplot(2,1,1) %[output:945efd8d]
plot(t_n,y_n,'r'); %[output:945efd8d]
xlabel('Time (s)'); %[output:945efd8d]
ylabel('Amplitude'); %[output:945efd8d]
title('Signal in time after adding noise'); %[output:945efd8d]
grid on; %[output:945efd8d]
%plotting in frequency domain after adding noise
Ny_n=length(y_n);
fy_n=(-Ny_n/2:Ny_n/2-1)*Fs/Ny_n;
subplot(2,1,2) %[output:945efd8d]
Y_n=fft(y_n);
plot(fy_n,fftshift(abs(Y_n)),'r') %[output:945efd8d]
xlabel('Frequency (Hz)'); %[output:945efd8d]
ylabel('Magnitude'); %[output:945efd8d]
title('Audio in frequency after adding noise'); %[output:945efd8d]
grid on; %[output:945efd8d]
% 4-LPF

fc = 3400 ; 
N = length(Y_n);

f_h = (-N/2:N/2-1)*(Fs/N);
H = double(abs(f_h) <= fc);
H = H(:);

Y_filtered = fftshift(Y_n) .* H;
y_filtered = real(ifft(ifftshift(Y_filtered)));
t_out = (0:length(y_filtered)-1)*Ts;


%plotting in time domain after filtering
figure(4) %[output:149dabba]
subplot(2,1,1); %[output:149dabba]
plot(t_out,y_filtered,'c'); %[output:149dabba]
xlabel('Time (s)'); %[output:149dabba]
ylabel('Amplitude'); %[output:149dabba]
title('Signal in time after filtering'); %[output:149dabba]
grid on; %[output:149dabba]
%plotting in freq domain after filtering
subplot(2,1,2); %[output:149dabba]
ny_f = length(y_filtered);

Y_out = fft(y_filtered);
f_out = (-ny_f/2:ny_f/2-1)*Fs/length(y_filtered);
plot(f_out, fftshift(abs(Y_out)),'c'); %[output:149dabba]
xlabel('Frequency (Hz)'); %[output:149dabba]
ylabel('Magnitude'); %[output:149dabba]
title('Audio in frequency after filtering'); %[output:149dabba]
grid on; %[output:149dabba]
%sound(y_filtered,Fs);



